"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   COLUMNS: () => (/* binding */ COLUMNS),\n/* harmony export */   getAllArticles: () => (/* binding */ getAllArticles),\n/* harmony export */   getArticleBySlug: () => (/* binding */ getArticleBySlug)\n/* harmony export */ });\nconst COLUMNS = [\n    {\n        slug: 'medical-deduction-basics',\n        title: '医療費控除とは？いくらから対象になる？10万円の壁と条件を解説',\n        category: '基礎知識',\n        description: '医療費控除はいくらから対象？10万円の基準だけでなく総所得5%の特例や家族合算、還付額の計算方法までわかりやすく解説します。無料・登録不要で試算可能。',\n        publishedAt: '2026-01-15',\n        updatedAt: '2026-02-01',\n        faq: [\n            {\n                question: '医療費が10万円未満でも控除を受けられますか？',\n                answer: 'はい。その年の総所得金額等が200万円未満（年収約300万円未満の給与所得者）の場合、総所得金額等の5%を超えた金額から医療費控除の対象になります。例えば総所得150万円なら7.5万円を超えた分が対象です。'\n            },\n            {\n                question: '生計を一にする家族の医療費も合算できますか？',\n                answer: '合算可能です。配偶者や子ども、仕送り中の大学生、同居の親族などの医療費をまとめて、世帯の中で最も所得が高い人が申告するのが最も節税効果が高くなります。'\n            }\n        ],\n        content: `\n## 医療費控除の基本｜年間10万円または「所得の5%」を超えたら対象\n\n医療費控除とは、1年間（1月1日〜12月31日）に支払った医療費が一定基準を超えた場合に、確定申考を行うことで所得税の還付や翌年の住民税減額を受けられる国の税制優遇制度です。\n\n一般的には「年間10万円以上」と言われますが、正確には次の計算式で求められます。\n\n【計算式】\n**医療費控除額 ＝ (支払った医療費の総額 － 保険金等で補填された金額) － 足切り額（10万円 または 総所得金額等の5%）**\n\n控除の上限額は最高 **200万円** です。\n\n---\n\n## 年収300万円未満なら「10万円未満」でも控除を受けられる仕組み\n\n総所得金額等が200万円未満の方（会社員で年収約297万円以下の方）は、足切り額が10万円ではなく **「総所得金額等の5%」** に引き下げられます。\n\n| 年間給与収入 | 概算総所得金額 | 医療費控除の足切りライン（5%） |\n| :--- | :--- | :--- |\n| **150万円** | 95万円 | **47,500円** |\n| **200万円** | 132万円 | **66,000円** |\n| **250万円** | 167万円 | **83,500円** |\n| **300万円以上** | 200万円以上 | **100,000円（一律）** |\n\nパートやアルバイト、新社会人、年金受給者などで医療費が年間6万円〜8万円程度かかった場合でも、控除を受けられるチャンスがあります。\n\n---\n\n## 生計を一にする「家族の医療費」は合算して申告できる\n\n医療費控除の最大のメリットは、**自己分だけでなく生計を一にする配偶者や子、親の医療費も合算して申告できる** 点です。\n\n- 単身赴任中の配偶者\n- 地方で暮らす仕送り中の大学生の子ども\n- 年金受給中で同居している両親\n\nこれらはすべて「生計を一にする親族」として合算可能です。家族の中で所得税率が最も高い人（通常は年収が一番高い人）がまとめて申告すると、戻ってくる還付金が最大化されます。\n\n---\n\n## 対象期間はいつからいつまで？「1月1日〜12月31日の支払い分」\n\n医療費控除の対象となるのは、**その年の1月1日から12月31日までに実際に支払った医療費** です。\n治療を受けた日ではなく「支払いを完了した日」が基準となるため、年末に受けた治療の支払いが翌年1月になった場合は、翌年分の控除対象になります。\n\nクレジットカード決済やデンタルローンを利用した場合は、信販会社が立替払いをした年（契約が成立した年）の控除対象として扱われます。\n\n---\n\n## 医療費控除で戻ってくる金額のシミュレーション例\n\n課税所得300万円（所得税率10%）の会社員が、家族で年間25万円の医療費を支払い、保険金で3万円補填された場合：\n\n1. **実質負担額**: 25万円 - 3万円 = 22万円\n2. **医療費控除額**: 22万円 - 10万円 = **12万円**\n3. **所得税還付額**: 12万円 × 10% × 1.021 = **約12,252円**\n4. **住民税軽減額**: 12万円 × 10% = **12,000円**\n5. **合計節税額**: **約24,252円**\n\n---\n\n## まとめ\n\n医療費控除は家族分をまとめたり、所得の低い方の特例を活用することで、10万円未満でも節税できる可能性があります。\n\n家族の医療費明細や年収を入力するだけで、還付額の目安が30秒でわかる[医療費控除の還付額計算シミュレーター](/)をぜひ試してみてください。\n`\n    },\n    {\n        slug: 'medical-deduction-calculation',\n        title: '【2026年最新】医療費控除の計算方法｜還付額の目安を簡単シミュレート',\n        category: '計算方法',\n        description: '医療費控除の計算式と還付金のシミュレーション手順を解説。所得税還付と住民税減額のダブル節税効果や年収別の目安がわかります。無料・登録不要で試算可能。',\n        publishedAt: '2026-01-18',\n        updatedAt: '2026-02-05',\n        faq: [\n            {\n                question: '控除額の全額がそのまま口座に振り込まれますか？',\n                answer: 'いいえ。控除額は「課税対象から差し引かれる金額」です。実際に振り込まれる還付金は「控除額 × 所得税率（+復興特別所得税）」となり、残りは翌年の住民税から減額されます。'\n            },\n            {\n                question: '復興特別所得税とは何ですか？',\n                answer: '東日本大震災からの復興財源として、2037年まで所得税額に対して2.1%が上乗せされる税金です。医療費控除による所得税還付の際も1.021倍されて計算されます。'\n            }\n        ],\n        content: `\n## 医療費控除額の基本計算式｜（支払った医療費 - 補填額）- 10万円\n\n医療費控除の計算手順は、以下の3つのステップで行います。\n\n1. **実質支払額の集計**: 1年間に支払った医療費の合計 － 保険金などで補填された金額\n2. **足切り額の減算**: 実質支払額 － 足切り額（※「10万円」または「総所得金額等の5%」のうち、いずれか少ない方の金額）\n3. **控除額の確定**: 最大200万円を上限として医療費控除額が決定\n\n【計算式】\n**実質負担額 ＝ 各医療費の支払額 － 各保険金等による補填額**\n\n注意点として、保険金の補填額は「その治療に直接関係する医療費」からのみ差し引き、他の病気の医療費から差し引くことはありません。\n\n---\n\n## 所得税の「還付額」と翌年の「住民税減額」のダブル節税効果\n\n医療費控除を申告すると、2つのルートで税金が軽減されます。\n\n1. **所得税の還付（指定口座へ振込）**\n   - 確定申告後、およそ1ヶ月〜1ヶ月半程度で税務署から指定口座に振り込まれます。\n   - 計算式: **医療費控除額 × 所得税率 × 1.021（復興特別所得税含む）**\n2. **住民税の減額（翌年6月からの住民税が安くなる）**\n   - 翌年6月から翌々年5月までの給与天引き住民税（または納付書）が安くなります。\n   - 計算式: **医療費控除額 × 10%（住民税所得割）**\n\n---\n\n## 【年収別】医療費15万円・20万円・30万円の場合の還付額目安表\n\n以下は給与所得者（単身または共働き）が医療費を支払った場合の、所得税還付＋住民税軽減の合計節税目安です。\n\n| 年収目安 | 限界所得税率 | 医療費15万円（控除5万） | 医療費20万円（控除10万） | 医療費30万円（控除20万） |\n| :--- | :--- | :--- | :--- | :--- |\n| **300万円** | 5% | 約7,550円 | 約15,100円 | 約30,210円 |\n| **500万円** | 10% | 約10,105円 | 約20,210円 | 約40,420円 |\n| **700万円** | 20% | 約15,210円 | 約30,420円 | 約60,840円 |\n| **1,000万円** | 33% | 約21,845円 | 約43,690円 | 約87,380円 |\n\n年収が高く所得税率が高い人ほど、同じ医療費でも戻ってくる金額が大きくなります。\n\n---\n\n## 保険金や高額療養費で補填された場合の注意点と計算方法\n\n生命保険の入院一時金や、健康保険の高額療養費、出産育児一時金などを受け取った場合は、医療費から差し引く必要があります。\n\n- **給付金 ＞ 該当の治療費** の場合: 差額が余っても他の科目の医療費からは引きません（0円として扱います）。\n- **年をまたいで支給された場合**: 医療費を支払った年の申告時に見込み額を差し引いて申告します。\n\n---\n\n## 計算間違いを防ぐ！医療費明細の効率的な集計ステップ\n\n1. 家族ごとに領収書を仕分ける\n2. 病院・薬局ごとに小計をまとめる\n3. 保険証の「医療費のお知らせ（医療費通知）」と照合する\n4. 通院交通費（電車・バス）をメモから書き出す\n\n---\n\n## まとめ\n\n控除額そのものがそのまま振り込まれるわけではなく、税率に応じた金額が所得税還付＋住民税減額として戻ってきます。\n\n複雑な控除額や住民税の減額分まで自動計算する[医療費控除の還付額計算ツール](/)なら、面倒な手計算なしで一発で節税額がわかります。\n`\n    },\n    {\n        slug: 'eligible-medical-expenses',\n        title: '医療費控除の対象になるもの・ならないもの一覧表【確定申告ガイド】',\n        category: '対象範囲',\n        description: '医療費控除の対象になる費用とならない費用の違いを一覧表で徹底整理。治療費・市販薬・歯科矯正・予防接種の境界線を解説します。無料・登録不要。',\n        publishedAt: '2026-01-20',\n        updatedAt: '2026-02-08',\n        faq: [\n            {\n                question: 'インフルエンザの予防接種は医療費控除になりますか？',\n                answer: '原則として対象外です。予防接種や病気予防目的のビタミン剤などは「治療目的」ではないため対象になりません。'\n            },\n            {\n                question: 'ドラッグストアで買った風邪薬は対象になりますか？',\n                answer: '治療目的で購入した風邪薬や頭痛薬は対象になります。また、セルフメディケーション税制対象マークのある市販薬はセルフメディケーション税制の対象としても集計できます。'\n            }\n        ],\n        content: `\n## 判断の基準は「治療・療養に必要な費用」かどうか\n\n国税庁の基本方針として、医療費控除の対象となるのは**「医師・歯科医師による治療または療養に直接必要と認められる費用」**です。\n一方で、「予防」「健康増進」「美容・見た目の改善」を目的とした出費は対象外となります。\n\n---\n\n## 【対象になる】病院代・処方薬・治療目的の歯科矯正・通院交通費\n\n以下のような費用は医療費控除の対象として計上できます。\n\n- 医師による診療代・検査代・入院費用\n- 処方せんに基づいて調剤された医薬品代\n- 治療目的で購入した市販の風邪薬・解熱鎮痛剤・湿布薬\n- 電車・バスなど公共交通機関を利用した通院交通費\n- 発育段階にある子どもの歯列矯正、咀嚼障害治療のための大人の歯列矯正\n- インプラント治療・セラミック歯・金歯・義歯（一般的な相場の範囲内）\n- 妊娠中の定期健診代・分べん費用・不妊治療費\n- 治療に必要な松葉杖・補聴器・義手義足の購入費用\n\n---\n\n## 【対象にならない】美容整形・インフルエンザ予防接種・サプリメント\n\n以下の費用は医療費控除の対象外となります。\n\n- 美容整形・二重手術・脂肪吸引などの審美目的の施術\n- ホワイトニングや見た目を良くするためだけの歯列矯正\n- インフルエンザやコロナウイルス等の予防接種費用\n- 人間ドック・健康診断費用（重大な病気が見つかり治療へ進んだ場合を除く）\n- 健康維持や疲労回復のためのビタミン剤・サプリメント・栄養ドリンク\n- 自家用車で通院した際のガソリン代・高速料金・駐車場代\n- 入院時の差額ベッド代（自己都合で個室を希望した場合）\n- 診断書・証明書の作成手数料\n\n---\n\n## 迷いやすいグレーゾーン費用（市販薬・マッサージ代・人間ドック）\n\n| 項目 | 対象になるケース | 対象外になるケース |\n| :--- | :--- | :--- |\n| **人間ドック・健康診断** | 検査で異常が見つかり、引き続き治療を行った場合 | 異常がなく健康維持・確認だけで終わった場合 |\n| **あん摩・マッサージ・鍼灸** | 国家資格者による治療目的の施術 | リラクゼーション・疲労回復・癒やし目的 |\n| **眼鏡・コンタクトレンズ** | 白内障手術後や弱視治療で医師の処方がある場合 | 一般的な視力矯正（近視・遠視・老眼） |\n| **差額ベッド代** | 病院側の都合や感染症対策等で個室に入った場合 | 患者や家族の希望で個室を選択した場合 |\n\n---\n\n## 領収書がない・紛失した場合の対処法と集計のコツ\n\n電車やバス代など領収書が出ない費用は、「利用日・乗車区間・金額・目的」を家計簿やメモアプリに記録しておけば申告可能です。\n万が一病院の領収書を紛失した場合は、再発行を依頼するか、健保から届く「医療費のお知らせ」で代替できる場合があります。\n\n---\n\n## まとめ\n\n治療に関わる費用は幅広く対象になりますが、予防や健康増進目的の費用は除外されるため整理が必要です。\n\n領収書ごとに金額を入れるだけでセルフメディケーション対象薬とも自動判別できる[医療費控除明細集計ツール](/)で準備を進めましょう。\n`\n    },\n    {\n        slug: 'transportation-costs',\n        title: '通院の交通費は医療費控除の対象？電車・バス・タクシーの判定基準',\n        category: '対象範囲',\n        description: '通院にかかった電車・バス・タクシー代は医療費控除できる？領収書がない場合のメモの残し方や自家用車ガソリン代の扱いを解説。無料・登録不要。',\n        publishedAt: '2026-01-22',\n        updatedAt: '2026-02-10',\n        faq: [\n            {\n                question: '通院のための電車代は領収書がなくても大丈夫ですか？',\n                answer: 'はい。電車や路線バスなどの領収書が発行されない交通機関は、日時・利用区間・運賃・通院先病院名をメモして「医療費控除の明細書」に記載すれば問題ありません。'\n            },\n            {\n                question: '子どもの通院に付き添った保護者の電車代も対象になりますか？',\n                answer: '対象になります。子どもが小さく一人で通院できない場合や、高齢者・歩行困難な患者の付き添いが必要不可欠な場合、付き添い人の交通費も認められます。'\n            }\n        ],\n        content: `\n## 電車・バスなど公共交通機関の運賃は原則すべて対象\n\n病院や診療所へ通院するために支払った**電車・地下鉄・路線バス・モノレールなどの運賃は、原則として全額が医療費控除の対象**となります。\n\n通院のための必要最小限かつ最も経済的なルート（通常利用する経路）の運賃が認められます。新幹線や特急列車を利用した遠方への通院も、地元で治療困難な難病で医師の紹介があるなど正当な理由があれば対象となります。\n\n---\n\n## タクシー代が認められるケース（緊急時・歩行困難・深夜など）\n\nタクシー代は「公共交通機関の利用が著しく困難である合理的な理由」がある場合に限り対象となります。\n\n- **対象になるケース**:\n  - 骨折や急病で歩行が困難な状態での通院\n  - 陣痛が始まり産院へ向かうためのタクシー利用\n  - 深夜・早朝で電車やバスが運行していない緊急時\n- **対象外になるケース**:\n  - 雨が降っていたからタクシーに乗った\n  - 荷物が多かった・疲れていた\n  - バス停まで歩くのが面倒だった\n\nタクシーを利用した際は、必ず運転手から領収書（レシート）を受け取り保管しておきましょう。\n\n---\n\n## 【対象外】自家用車のガソリン代・駐車場代・高速道路料金\n\n車で通院する方も多いですが、税法上の規定により以下の費用は**一切対象外**となります。\n\n- 通院にかかったガソリン代\n- 病院や周辺コインパーキングの駐車料金\n- 高速道路・有料道路の通行料金\n- レンタカー費用やカーシェア利用料\n\n---\n\n## 領収書がない電車・バス代のメモ・明細の残し方\n\nSuicaやPASMOなどのICカード履歴や、スマートフォンのメモ帳に以下の4点を記録しておきます。\n\n1. **利用日（通院日）**\n2. **通院した人（氏名）**\n3. **利用区間（例: ○○駅 〜 △△駅 / 市営バス ○○停留所 〜 △△前）**\n4. **支払金額（往復運賃）**\n\n確定申告時には、これらをまとめて「医療費控除の明細書」の交通費欄に集計して記入します。\n\n---\n\n## 付き添い人の交通費は対象になる？（子供・高齢者の通院）\n\n患者本人が幼少の子どもである場合や、高齢・病気により一人で安全に通院できない場合、**付き添う保護者・介助者の交通費も医療費控除の対象**として合算できます。\nただし、付き添い人が2名以上いる場合の余分な交通費や、遠方からの見舞いに駆けつけた親族の交通費は対象外です。\n\n---\n\n## まとめ\n\n電車代やバス代は領収書がなくても日時のメモがあれば申告可能です。忘れずに集計しておきましょう。\n\n電車代やバス代を明細に追加入力して還付額をシミュレーションできる[医療費控除計算ツール](/)をご活用ください。\n`\n    },\n    {\n        slug: 'family-deduction-comparison',\n        title: '家族の医療費は誰が申告すると一番得？共働き世帯の節税テクニック',\n        category: '節税テクニック',\n        description: '共働き世帯で家族の医療費を合算する場合、夫と妻どちらが申告すると還付額が一番高くなるかを具体的なシミュレーションで解説。無料・登録不要。',\n        publishedAt: '2026-01-25',\n        updatedAt: '2026-02-12',\n        faq: [\n            {\n                question: '妻が自分のクレジットカードで払った医療費を夫が申告してもいいですか？',\n                answer: '問題ありません。医療費控除では「誰が生計を一にして支払ったか（世帯の財布）」が基準となるため、支払名義が妻であっても夫がまとめて申告可能です。'\n            },\n            {\n                question: '夫婦それぞれが別々に医療費控除を申告することはできますか？',\n                answer: '可能ですがおすすめしません。それぞれで足切り額（10万円）が引かれてしまうため、一人の申告にまとめたほうが足切りを1回で済ませられ、高い税率が適用されて大幅にお得になります。'\n            }\n        ],\n        content: `\n## 原則「一番所得（税率）が高い人」がまとめて申告するのが一番得\n\n医療費控除の節税額は、申告者の限界所得税率に直結します。\n日本の所得税は「累進課税」を採用しているため、所得が多い人ほど税率が高く設定されています。\n\nそのため、家族全員の医療費を**最も年収（所得税率）が高い家族の名義で一括申告する**のが鉄則です。\n\n---\n\n## 共働き夫婦で「妻のほうが医療費が多い」場合でも夫が申告していい？\n\nよくある勘違いとして「妻の治療費だから妻が申告しなければならない」というものがありますが、これは誤りです。\n\n生計を一にしている夫婦であれば、妻の不妊治療費や出産費用、歯科矯正代であっても、**夫の確定申告でまとめて全額を控除申請できます**。誰の口座やクレジットカードから引き落とされたかも問われません。\n\n---\n\n## 生計を一にする家族の範囲（離れて暮らす仕送り中の大学生や両親）\n\n「生計を一にする」とは、同居していることだけを意味しません。\n\n- **一人暮らしの大学生の子ども**: 仕送りで生活費や学費を援助していれば対象\n- **別居の高齢の両親**: 定期的に生活費や医療費を仕送りして扶養していれば対象\n- **単身赴任中の配偶者**: 週末に帰宅したり生活費を送金していれば対象\n\n別居の家族の医療費領収書も手元に集めて合算申告しましょう。\n\n---\n\n## 【シミュレーション】夫が申告vs妻が申告で還付額が2万円変わる例\n\n**【前提条件】**\n- 夫: 年収650万円（所得税率20%）\n- 妻: 年収300万円（所得税率10%）\n- 家族全体の医療費実質負担額: 30万円（控除額20万円）\n\n| 申告パターン | 所得税還付額 | 住民税軽減額 | 合計節税額 |\n| :--- | :--- | :--- | :--- |\n| **夫がまとめて申告** | 20万 × 20% × 1.021 = **40,840円** | 20万 × 10% = **20,000円** | **60,840円** |\n| **妻がまとめて申告** | 20万 × 10% × 1.021 = **20,420円** | 20万 × 10% = **20,000円** | **40,420円** |\n| **差額（お得度）** | - | - | **夫が20,420円お得！** |\n\nこのように、申告者を夫にするだけで約2万円も手取りが増えることになります。\n\n---\n\n## 家族合算で申告する際の注意点と申告手順\n\n1. 家族全員の領収書を「人別・病院別」に分類する\n2. 申告者本人の確定申告書に「生計を一にする親族の医療費」として記入する\n3. 夫婦どちらかが「ふるさと納税」を限度額いっぱい行っている場合は、その上限額の変動も考慮する\n\n---\n\n## まとめ\n\n世帯全体の節税額を最大化するには、税率の高い家族へ医療費を集約するのが基本テクニックです。\n\n夫と妻の年収を入れるだけで「どちらが申告すると何円得か」を自動判定する[世帯内申告者比較機能つき計算ツール](/)でチェックしてみましょう。\n`\n    },\n    {\n        slug: 'self-medication-tax-system',\n        title: 'セルフメディケーション税制とは？通常の医療費控除との違いと選び方',\n        category: '税制比較',\n        description: '市販薬の購入で使えるセルフメディケーション税制と通常の医療費控除の違いを比較。どちらがお得になるかの判定フローを公開。無料・登録不要。',\n        publishedAt: '2026-01-28',\n        updatedAt: '2026-02-15',\n        faq: [\n            {\n                question: '通常の医療費控除とセルフメディケーション税制は両方使えますか？',\n                answer: 'いいえ、併用はできません。どちらか一方を申告者が選択して確定申告する必要があります。'\n            },\n            {\n                question: 'セルフメディケーション税制の対象医薬品はどうやって見分けますか？',\n                answer: 'パッケージに共通識別マーク（セルフメディケーションマーク）が印字されているほか、レシートの商品名横に「★」や「※セルフメディケーション対象」などの記載があります。'\n            }\n        ],\n        content: `\n## セルフメディケーション税制の概要｜対象となる「スイッチOTC医薬品」とは\n\nセルフメディケーション税制（医療費控除の特例）は、健康の維持増進や疾病予防への取り組みを行う個人が、対象となる**「スイッチOTC医薬品（要指導医薬品及び一般用医薬品）」**を購入した際に受けられる税制優遇です。\n\n病院にかかるほどではない風邪や頭痛、胃痛などで、薬局やドラッグストアで市販薬を自主的に購入してセルフケアを行った人を支援する制度です。\n\n---\n\n## 年間1万2,000円超で購入した場合に適用（上限8万8,000円）\n\nセルフメディケーション税制の控除額計算式は非常にシンプルです。\n\n【計算式】\n**セルフメディケーション税制控除額 ＝ 対象医薬品の年間購入額 － 1万2,000円（控除上限 8万8,000円）**\n\n通常の医療費控除が「足切り10万円」なのに対し、**セルフメディケーション税制は「1万2,000円」から対象**となるため、病院にはあまり行かないけれど市販薬をよく買う世帯に有利です。\n\n---\n\n## 通常の医療費控除とセルフメディケーション税制は「併用不可（選択制）」\n\n重要なルールとして、**同じ年に「通常の医療費控除」と「セルフメディケーション税制」を重複して適用することはできません**。\n\n申告する人が確定申告時にどちらか1つを選択する必要があります。\n\n| 項目 | 通常の医療費控除 | セルフメディケーション税制 |\n| :--- | :--- | :--- |\n| **対象費用** | 病院代・処方薬・通院交通費・市販薬 | スイッチOTC医薬品（対象マーク付き市販薬） |\n| **足切り額** | 10万円（所得200万未満は総所得5%） | **1万2,000円** |\n| **控除限度額** | **200万円** | 8万8,000円（購入額10万円で到達） |\n| **適用条件** | 特になし | 健診・予防接種・がん検診などの受診 |\n\n---\n\n## 【判定フロー】自分はどっちを選ぶべき？（病院代が多いか/薬代が多いか）\n\n1. **病院代（入院・手術・歯科・通院）が年間10万円以上ある**\n   → **通常の医療費控除** を選択するのが確実にお得。\n2. **病院にはほぼ行かなかったが、ドラッグストアで対象薬を年間3万円以上買った**\n   → **セルフメディケーション税制** を選択すれば節税可能。\n3. **病院代が8万円、対象市販薬が4万円など微妙なライン**\n   → 双方の控除額を計算し、控除額が大きい方を選択する。\n\n---\n\n## 適用に必要な「健康の保持増進の取り組み」（健診・予防接種など）\n\nセルフメディケーション税制を利用するには、申告する人がその年に以下のいずれかの「取り組み」を行っている必要があります。\n\n- 勤務先の定期健康診断（職場の健診）\n- 市区町村のメタボ健診（特定健康診査）\n- インフルエンザ等の予防接種\n- 市区町村のがん検診\n- 人間ドック\n\n確定申告書に受診した健診の名称や受診日を記載します。\n\n---\n\n## まとめ\n\n病院代が少なめで市販薬の購入が多い世帯は、セルフメディケーション税制を選んだほうがお得になります。\n\n薬代と病院代を入力するだけで「通常控除vsセルフメディケーション」のどちらが何円得かを自動判定する[両制度比較対応計算ツール](/)が便利です。\n`\n    },\n    {\n        slug: 'furusato-tax-deduction-impact',\n        title: '医療費控除と「ふるさと納税」を併用すると損する？上限額への影響と対策',\n        category: '併用・特例',\n        description: '医療費控除とふるさと納税を併用すると上限額はどうなる？損をしないための注意点とワンストップ特例から確定申告への切替を解説。無料・登録不要。',\n        publishedAt: '2026-02-01',\n        updatedAt: '2026-02-18',\n        faq: [\n            {\n                question: 'ふるさと納税でワンストップ特例を申請済みですが、医療費控除をする場合はどうなりますか？',\n                answer: '確定申告書を提出した時点でワンストップ特例はすべて無効になります。確定申告書に医療費控除だけでなく「ふるさと納税（寄附金控除）」の金額も必ず含めて申告してください。'\n            },\n            {\n                question: '医療費控除を使うと、ふるさと納税の上限額はどれくらい減りますか？',\n                answer: '医療費控除額の約2%〜5%程度、ふるさと納税の上限額が下がります。例えば医療費控除10万円の場合、ふるさと納税上限額は約2,000円〜3,000円程度下がります。'\n            }\n        ],\n        content: `\n## 医療費控除を受けると「ふるさと納税の上限額（自己負担2,000円枠）」が少し下がる\n\n「医療費控除とふるさと納税を併用すると損をする」という噂を耳にしたことがあるかもしれませんが、**トータルでは必ず得をします**。\n\nただし、医療費控除を適用すると、ふるさと納税の「実質自己負担2,000円で寄附できる上限枠」がわずかに縮小（減少）することは事実です。\n\n---\n\n## なぜ下がる？住民税所得割額が安くなるメカニズム\n\nふるさと納税の特例控除限度額は、**「個人住民税所得割額の20%」** を基準に計算されています。\n\n1. 医療費控除を申告する\n2. 課税所得が減り、翌年の住民税所得割額が安くなる\n3. 住民税所得割額の20%枠（ふるさと納税上限）も連動して少し小さくなる\n\n---\n\n## 【試算】医療費控除10万円を受けるとふるさと納税の上限はいくら減る？\n\n医療費控除によるふるさと納税上限額の減少額は、以下の計算式でおおよそ見積もることができます。\n\n【減少目安】\n**ふるさと納税の上限減少額 ＝ 医療費控除額 × 約2%〜5%**\n\n| 年収目安 | 医療費控除額 | ふるさと納税上限減少の目安 |\n| :--- | :--- | :--- |\n| **年収400万円** | 10万円 | **約2,000円** 減少 |\n| **年収600万円** | 10万円 | **約2,400円** 減少 |\n| **年収800万円** | 20万円 | **約5,800円** 減少 |\n| **年収1,000万円** | 50万円 | **約18,000円** 減少 |\n\nすでに上限ギリギリまでふるさと納税を行っていた場合、上限を超えた数百円〜数千円分が自己負担となる可能性がありますが、**医療費控除によって得られる還付額（数万円）のほうが圧倒的に大きい**ため、迷わず申告すべきです。\n\n---\n\n## ワンストップ特例制度は使えない！確定申告への切り替えが必要な理由\n\nふるさと納税の「ワンストップ特例申請書」を自治体に郵送していた方でも、**医療費控除のために確定申告書を提出するとワンストップ特例は自動的にすべて無効化**されます。\n\n確定申告を行う際は、医療費控除だけでなく、**ふるさと納税した自治体すべての「寄附金受領証明書」をもとに寄附金控除も忘れずに入力**してください。\n\n---\n\n## 併用しても「トータルの節税額」は必ず得になる理由\n\n例えば、年収500万円の人が医療費控除10万円を受けると約20,000円が節税されます。\nふるさと納税の上限が約2,400円下がって自己負担が増加したとしても、\n\n【節税効果の比較】\n**世帯の手残り純増 ＝ ＋20,000円（医療費控除による節税） － 2,400円（ふるさと納税自己負担増） ＝ ＋17,600円**\n\nとなり、世帯全体の手取りは確実に大きくプラスになります。\n\n---\n\n## まとめ\n\nふるさと納税の上限額は少し下がりますが、医療費控除と併用したほうが世帯全体の節税効果は圧倒的に高くなります。\n\n医療費控除を適用したあとの「ふるさと納税上限額の減少目安」も同時に確認できる[医療費控除・ふるさと納税シミュレーター](/)で安心準備を進めましょう。\n`\n    },\n    {\n        slug: 'tax-return-procedure-guide',\n        title: '【初心者向け】医療費控除の確定申告やり方ガイド｜明細書の書き方と準備',\n        category: '確定申告手順',\n        description: '医療費控除の確定申告に必要な書類や明細書の書き方をステップ形式で解説。スマホでのe-Tax申告や領収書の保管ルールも網羅。無料・登録不要。',\n        publishedAt: '2026-02-05',\n        updatedAt: '2026-02-20',\n        faq: [\n            {\n                question: '確定申告の期間はいつからいつまでですか？',\n                answer: '通常の確定申告期間は毎年2月16日〜3月15日です。ただし、税金が戻ってくる「還付申告」だけであれば、該当年の翌年1月1日から5年間いつでも提出可能です。'\n            },\n            {\n                question: 'マイナンバーカードがなくてもスマホで確定申告できますか？',\n                answer: '税務署で事前に「ID・パスワード」を発行してもらっていれば可能です。また、スマホやパソコンで作成した申告書を紙で印刷して郵送提出することもできます。'\n            }\n        ],\n        content: `\n## 確定申告に必要な持ち物・書類（源泉徴収票・医療費通知・領収書など）\n\n医療費控除の申告準備に必要なアイテムは以下の通りです。\n\n- **源泉徴収票**（会社員・年金受給者の方）\n- **医療費の領収書・レシート**（または健康保険組合の「医療費のお知らせ」）\n- **通院交通費のメモ**（日時・区間・運賃）\n- **マイナンバーカード**（またはマイナンバー通知カード＋身分証）\n- **還付金の振込先口座番号**（申告者本人名義のもの）\n- **スマートフォン**（マイナンバーカード読み取り対応端末）\n\n---\n\n## 領収書の提出は不要！ただし「5年間の自宅保管」が義務\n\n平成29年（2017年）分の確定申告から、**医療費の領収書を税務署へ提出・提示する必要はなくなりました**。\n\nその代わり、領収書をもとに「医療費控除の明細書」を作成して提出します。\n提出した領収書は、税務署から提示・提出を求められることがあるため、**確定申告期限の翌日から5年間は自宅で大切に保管**する義務があります。\n\n---\n\n## 「医療費控除の明細書」の書き方と効率的なグループ分けのコツ\n\n明細書には領収書を1枚ずつ書く必要はありません。**「医療を受けた人」ごとに「病院・薬局などの支払先」ごとにまとめて1行**で記入できます。\n\n1. **医療を受けた方の氏名**: （例: 太郎、花子）\n2. **病院・薬局などの支払先の名称**: （例: ○○総合病院、△△薬局）\n3. **医療費の区分**: 診療・治療 / 医薬品購入 / 介護 / その他の該当にチェック\n4. **支払った医療費の額**: その病院・薬局での年間合計額\n5. **補填された金額**: 保険金等でカバーされた合計額\n\n---\n\n## 国税庁「確定申告書等作成コーナー」でのスマホ申告手順\n\n国税庁のウェブサイト「確定申告書等作成コーナー」を使えば、画面の案内に従うだけでスマホから簡単にe-Tax送信できます。\n\n1. スマホで「確定申告書等作成コーナー」にアクセス\n2. 「作成開始」をタップし、マイナンバーカードを読み取る\n3. 源泉徴収票のカメラ読み取りまたは数値を入力\n4. 控除項目で「医療費控除」を選択し、明細を入力\n5. 還付金額を確認し、振込口座を入力して送信完了！\n\n---\n\n## 還付金はいつ振込される？（申告から1ヶ月前後が目安）\n\n- **e-Tax（電子申告）の場合**: 申告書提出からおよそ **2週間〜3週間程度**\n- **書面（郵送・窓口提出）の場合**: 申告書提出からおよそ **1ヶ月〜1ヶ月半程度**\n\n還付金の処理状況は、国税庁のe-Taxマイページからリアルタイムで確認できます。\n\n---\n\n## まとめ\n\n事前に人ごと・病院ごとに領収書をまとめて集計しておけば、確定申告の作業は驚くほどスムーズに終わります。\n\n病院や薬局ごとの金額を入力してA4印刷やCSV出力ができる[医療費控除集計・明細出力ツール](/)を使えば、申告書への転記も一瞬です。\n`\n    },\n    {\n        slug: 'dental-treatment-deduction',\n        title: '歯科の治療費や歯列矯正は医療費控除の対象？インプラントやセラミックの扱い',\n        category: '歯科・高額医療',\n        description: '高額なインプラントや大人の歯列矯正、セラミック治療は医療費控除の対象になる？デンタルローンの注意点や判定条件を解説。無料・登録不要。',\n        publishedAt: '2026-02-08',\n        updatedAt: '2026-02-22',\n        faq: [\n            {\n                question: '大人の歯列矯正は医療費控除の対象になりますか？',\n                answer: '噛み合わせの改善など咀嚼障害を治療する目的であれば対象になります。単に見た目をきれいにする美容目的の場合は対象外です。念のため歯科医師に「診断書」をもらっておくと安心です。'\n            },\n            {\n                question: 'デンタルローンで分割払いした場合、金利手数料も医療費控除できますか？',\n                answer: 'いいえ、金利手数料は対象外です。治療費本体の金額のみが医療費控除の対象となります。'\n            }\n        ],\n        content: `\n## 歯科治療で対象になるもの（保険診療・虫歯治療・金歯・インプラント等）\n\n自費診療（自由診療）が多く高額になりやすい歯科治療ですが、その多くが医療費控除の対象となります。\n\n- **対象になる歯科治療**:\n  - 保険適用の虫歯治療・歯周病治療・抜歯\n  - インプラント（人工歯根）治療費用\n  - セラミックインレー・クラウン（一般的な材料と認められるもの）\n  - 金歯・白金加金などの詰め物・被せ物\n  - 親知らずの抜歯およびそれに伴う処方薬\n\n---\n\n## 歯列矯正は「機能的欠陥の治療」なら対象、「見た目の美容目的」は不可\n\n歯列矯正の可否は、その目的によって明確に分かれます。\n\n- **対象になるケース**:\n  - 咀嚼障害（噛み合わせが悪く食事がうまくできない）の治療\n  - 顎変形症や発音障害を治すための矯正\n  - 歯科医師から「治療が必要」と診断された場合\n- **対象外になるケース**:\n  - 歯並びを整えて口元の見た目を美しくしたい（審美目的）\n  - ホワイトニング治療\n\n成人（大人）の矯正の場合は、確定申告時に税務署から説明を求められることがあるため、歯科医師に**「咀嚼改善等の医療目的である診断書」**を発行してもらうのが確実です。\n\n---\n\n## 子どもの歯列矯正は原則すべて対象（発育段階での咀嚼障害防止）\n\n発育段階にある成長期の子どもの歯列矯正は、正常な発育や噛み合わせを確保するための医療行為とみなされるため、**原則としてすべて医療費控除の対象**となります。\n\n---\n\n## デンタルローンや分割払いで支払った場合の医療費控除の注意点\n\n高額な歯科治療でデンタルローン（信販会社の立替払い）やクレジットカード分割払いを利用した場合、**信販会社が病院に立替払いをした年（契約成立年）の医療費控除**として一括申告します。\n\n自分の口座からの引き落としが翌年以降にわたる場合でも、治療費の全額をその年の医療費として計上できます。\n\n---\n\n## 歯科ローン利用時の「金利手数料」は対象外になる点に注意\n\nデンタルローンを利用した際の分割手数料や利息（金利相当分）は、信販会社に対する利息支払いであり治療費そのものではないため、**医療費控除の対象外**となります。\n\n申告する際は、ローン契約書から「治療費本体」の金額のみを抽出して記載してください。\n\n---\n\n## まとめ\n\n高額なインプラントや治療目的の矯正は医療費控除の大きな節税チャンスです。診断書や領収書をしっかり保管しましょう。\n\nインプラントや矯正費用を入力して、所得税の還付額と住民税の減額分を[高額医療費対応計算ツール](/)で確認できます。\n`\n    },\n    {\n        slug: 'insurance-claim-reimbursement',\n        title: '保険金や高額療養費が出たときの医療費の計算｜引き方の正しいルール',\n        category: '計算方法',\n        description: '生命保険の入院給付金や高額療養費を受け取った際の正しい補填額の引き方ルールを解説。引ききれない場合の注意点も図解。無料・登録不要。',\n        publishedAt: '2026-02-12',\n        updatedAt: '2026-02-25',\n        faq: [\n            {\n                question: '給付金が治療費よりも多くて余った場合、他の家族の医療費から引く必要がありますか？',\n                answer: '引く必要はありません。補填額はその目的となった治療費からのみ差し引き、余った金額は0円として扱います。他の治療費や家族の医療費を減額する必要はありません。'\n            },\n            {\n                question: '出産育児一時金（50万円）も医療費から引かなければいけませんか？',\n                answer: 'はい。出産育児一時金は出産費用を補填するための給付金ですので、かかった分娩・入院費用から差し引いて計算します。'\n            }\n        ],\n        content: `\n## 医療費控除から差し引く「補填金」の代表例（入院給付金・高額療養費・出産育児一時金）\n\n医療費控除では、実際に自分で負担した金額だけが控除対象となるため、公的制度や民間保険から支払われた補填金は差し引かなければなりません。\n\n- **差し引く必要がある補填金**:\n  - 生命保険・医療保険の入院給付金・手術給付金\n  - 健康保険から支給される高額療養費\n  - 健保組合独自の付加給付金\n  - 出産育児一時金・家族出産育児一時金\n  - 交通事故等の加害者から受け取った損害賠償金（治療費相当分）\n- **差し引かなくてよいもの**:\n  - 傷病手当金（生活保障のため）\n  - 出産手当金\n  - がん診断給付金（使途自由な一時金）\n  - 死亡保険金\n\n---\n\n## 重要ルール！補填額は「その給付の対象となった医療費」からしか引けない\n\nこれが医療費控除の計算で最も重要かつ間違えやすいルールです。\n\n補填金は、**「その給付を受ける原因となった特定の病気やケガの医療費」からのみ差し引きます**。年間の医療費総額から一括で引き算してはいけません。\n\n---\n\n## 【計算例】保険金が多くてマイナスになった場合、他の医療費から引いていい？\n\n**【具体例】**\n- 夫の盲腸手術・入院費: 15万円 ／ 入院給付金: **20万円**（+5万円余り）\n- 妻の歯科治療費: 10万円 ／ 給付金: 0円\n\n【正しい計算結果】\n- **夫の実質負担**: 15万円 － 20万円 ＝ **0円**（給付金が5万円余ってもマイナスにならず0円扱い）\n- **妻の実質負担**: 10万円 － 0円 ＝ **10万円**\n- **世帯の実質医療費負担**: 0円 ＋ 10万円 ＝ **10万円**\n\nもし総額から一括で引いてしまうと「(15万円 ＋ 10万円) － 20万円 ＝ 5万円」と誤計算してしまい、本来受けられる控除を失ってしまいます。給付金は該当する治療費から個別に差し引くのが正しいルールです。\n\n---\n\n## 年をまたいで保険金が振り込まれた場合の申告方法\n\n12月に手術を受け、保険金や高額療養費が翌年2月に振り込まれた場合でも、**その手術費用を支払った年の医療費控除申告で見込み額を差し引いて申告**します。\n\n万が一、確定申告後に確定した給付金額が見込みと異なっていた場合は、修正申告または更正の請求を行います。\n\n---\n\n## 補填金を引いたあとの実質負担額の集計ステップ\n\n1. 領収書と保険金給付明細書（共済・民間保険）を並べる\n2. 給付金がどの入院・治療に対応しているかを紐付ける\n3. 該当の治療費ごとに差し引き計算を行う\n4. 集計した実質負担額から足切り額（10万円）を引いて控除額を算出する\n\n---\n\n## まとめ\n\n保険金はすべての医療費総額から引くのではなく、該当する病気の治療費からのみ差し引くのが正しいルールです。\n\n支払い金額と保険金の補填額を個別にセットして正しい控除額を算出できる[保険金補填対応・医療費控除計算ツール](/)をご利用ください。\n`\n    }\n];\nfunction getAllArticles() {\n    return COLUMNS;\n}\nfunction getArticleBySlug(slug) {\n    return COLUMNS.find((a)=>a.slug === slug);\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/lib/columns.ts\n");

